for zh, en, n in PAIRS:
    found = s.count(zh)
    if found != n:
        sys.exit(f'生成英文页失败：中文页中应有 {n} 处、实际 {found} 处匹配以下文案，请同步更新 scripts/configssh_gen_en.py：\n{zh}')
    s = s.replace(zh, en)

Path(dst).parent.mkdir(parents=True, exist_ok=True)
